// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title EncryptedEscrow
 * @notice Escrow contract with encrypted order metadata stored on-chain
 * @dev Payment amounts are committed via hash, revealed at settlement
 */
contract EncryptedEscrow is ReentrancyGuard, Ownable {
    struct Order {
        address buyer;
        address seller;
        bytes32 amountCommitment; // keccak256(abi.encodePacked(amount, salt))
        bytes encryptedMetadata;  // encrypted order details
        uint256 depositedWei;
        uint256 revealedAmount;
        OrderState state;
        uint64 createdAt;
        uint64 revealDeadline;
    }

    enum OrderState { Created, Funded, Revealed, Settled, Disputed, Refunded }

    mapping(uint256 => Order) public orders;
    mapping(address => uint256) public sellerCollateral;
    uint256 public nextOrderId;
    uint256 public constant MIN_COLLATERAL = 0.1 ether;
    uint256 public constant REVEAL_WINDOW = 24 hours;
    uint256 public protocolFeesBps = 50; // 0.5%
    uint256 public collectedFees;

    event OrderCreated(uint256 indexed orderId, address buyer, address seller);
    event OrderFunded(uint256 indexed orderId, uint256 amount);
    event AmountRevealed(uint256 indexed orderId, uint256 amount);
    event OrderSettled(uint256 indexed orderId);
    event OrderRefunded(uint256 indexed orderId);

    modifier onlyBuyer(uint256 orderId) {
        require(msg.sender == orders[orderId].buyer, "Not buyer");
        _;
    }

    modifier onlySeller(uint256 orderId) {
        require(msg.sender == orders[orderId].seller, "Not seller");
        _;
    }

    function depositCollateral() external payable {
        require(msg.value >= MIN_COLLATERAL, "Insufficient collateral");
        sellerCollateral[msg.sender] += msg.value;
    }

    function createOrder(
        address _seller,
        bytes32 _amountCommitment,
        bytes calldata _encryptedMetadata
    ) external returns (uint256 orderId) {
        require(sellerCollateral[_seller] >= MIN_COLLATERAL, "Seller not collateralized");
        orderId = nextOrderId++;
        orders[orderId] = Order({
            buyer: msg.sender,
            seller: _seller,
            amountCommitment: _amountCommitment,
            encryptedMetadata: _encryptedMetadata,
            depositedWei: 0,
            revealedAmount: 0,
            state: OrderState.Created,
            createdAt: uint64(block.timestamp),
            revealDeadline: 0
        });
        emit OrderCreated(orderId, msg.sender, _seller);
    }

    function fundOrder(uint256 orderId) external payable onlyBuyer(orderId) nonReentrant {
        Order storage order = orders[orderId];
        require(order.state == OrderState.Created, "Invalid state");
        require(msg.value > 0, "Must send ETH");
        order.depositedWei += msg.value;
        order.state = OrderState.Funded;
        order.revealDeadline = uint64(block.timestamp + REVEAL_WINDOW);
        emit OrderFunded(orderId, msg.value);
    }

    function revealAmount(
        uint256 orderId,
        uint256 _amount,
        bytes32 _salt
    ) external onlyBuyer(orderId) {
        Order storage order = orders[orderId];
        require(order.state == OrderState.Funded, "Not funded");
        require(block.timestamp <= order.revealDeadline, "Reveal expired");
        bytes32 computed = keccak256(abi.encodePacked(_amount, _salt));
        require(computed == order.amountCommitment, "Invalid reveal");
        require(_amount <= order.depositedWei, "Amount exceeds deposit");
        require(_amount > 0, "Amount must be positive");
        order.revealedAmount = _amount;
        order.state = OrderState.Revealed;
        emit AmountRevealed(orderId, _amount);
    }

    function settleOrder(uint256 orderId) external onlySeller(orderId) nonReentrant {
        Order storage order = orders[orderId];
        require(order.state == OrderState.Revealed, "Not revealed");
        require(order.revealedAmount > 0, "No amount revealed");

        uint256 payment = order.revealedAmount;
        uint256 fee = _calculateFee(payment);
        uint256 sellerPayout = payment - fee;
        uint256 buyerRefund = order.depositedWei - payment;

        order.state = OrderState.Settled;
        collectedFees += fee;

        // Pay seller
        (bool s1,) = order.seller.call{value: sellerPayout}("");
        require(s1, "Seller transfer failed");

        // Refund excess to buyer
        if (buyerRefund > 0) {
            (bool s2,) = order.buyer.call{value: buyerRefund}("");
            require(s2, "Buyer refund failed");
        }
        emit OrderSettled(orderId);
    }

    function requestRefund(uint256 orderId) external onlyBuyer(orderId) nonReentrant {
        Order storage order = orders[orderId];
        require(
            order.state == OrderState.Funded && block.timestamp > order.revealDeadline,
            "Cannot refund"
        );
        uint256 refundAmount = order.depositedWei;
        order.state = OrderState.Refunded;
        (bool success,) = order.buyer.call{value: refundAmount}("");
        require(success, "Refund failed");
        emit OrderRefunded(orderId);
    }

    function _calculateFee(uint256 amount) internal view returns (uint256) {
        // Fee calculation - minimum 1 wei fee for any non-zero amount
        uint256 fee = (amount * protocolFeesBps) / 10000;
        if (fee == 0 && amount > 0) fee = 1;
        return fee;
    }

    function disputeOrder(uint256 orderId) external {
        Order storage order = orders[orderId];
        require(
            msg.sender == order.buyer || msg.sender == order.seller,
            "Not party"
        );
        require(
            order.state == OrderState.Funded || order.state == OrderState.Revealed,
            "Cannot dispute"
        );
        order.state = OrderState.Disputed;
    }

    function resolveDispute(
        uint256 orderId,
        uint256 buyerShare,
        uint256 sellerShare
    ) external onlyOwner nonReentrant {
        Order storage order = orders[orderId];
        require(order.state == OrderState.Disputed, "Not disputed");
        require(buyerShare + sellerShare == order.depositedWei, "Must distribute all funds");

        order.state = OrderState.Settled;

        if (buyerShare > 0) {
            (bool s1,) = order.buyer.call{value: buyerShare}("");
            require(s1, "Buyer transfer failed");
        }
        if (sellerShare > 0) {
            (bool s2,) = order.seller.call{value: sellerShare}("");
            require(s2, "Seller transfer failed");
        }
    }

    function withdrawFees() external onlyOwner {
        uint256 amount = collectedFees;
        collectedFees = 0;
        (bool success,) = owner().call{value: amount}("");
        require(success, "Withdraw failed");
    }

    function withdrawCollateral(uint256 amount) external nonReentrant {
        require(sellerCollateral[msg.sender] >= amount, "Insufficient");
        sellerCollateral[msg.sender] -= amount;
        (bool success,) = msg.sender.call{value: amount}("");
        require(success, "Withdraw failed");
    }
}
